import{_ as t,o as a,c as i,ag as s}from"./chunks/framework.BwSLX4ak.js";const p=JSON.parse('{"title":"AllMusic 外置音乐源","description":"","frontmatter":{},"headers":[],"relativePath":"allmusic/index.md","filePath":"allmusic/index.md"}'),l={name:"allmusic/index.md"};function o(c,e,u,r,d,h){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="allmusic-外置音乐源" tabindex="-1">AllMusic 外置音乐源 <a class="header-anchor" href="#allmusic-外置音乐源" aria-label="Permalink to &quot;AllMusic 外置音乐源&quot;">​</a></h1><p>QQMusic 与 Kugou 为 AllMusic 提供音乐源接口。AllMusic 负责玩家命令、播放队列和客户端通信，音乐源负责搜索、歌曲信息、播放地址、封面与歌词。</p><table tabindex="0"><thead><tr><th>音乐源</th><th>API ID</th><th>源码</th><th>下载</th></tr></thead><tbody><tr><td>QQ 音乐</td><td><code>qqmusic</code></td><td><a href="https://github.com/hutuyee/AllMusic_QQMusic" target="_blank" rel="noreferrer">AllMusic_QQMusic</a></td><td><a href="https://github.com/hutuyee/AllMusic_QQMusic/releases" target="_blank" rel="noreferrer">Releases</a></td></tr><tr><td>酷狗音乐</td><td><code>kugou</code></td><td><a href="https://github.com/hutuyee/AllMusic_Kugou" target="_blank" rel="noreferrer">AllMusic_Kugou</a></td><td><a href="https://github.com/hutuyee/AllMusic_Kugou/releases" target="_blank" rel="noreferrer">Releases</a></td></tr></tbody></table><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><ol><li>安装与你的平台匹配的 <a href="https://github.com/Coloryr/AllMusic" target="_blank" rel="noreferrer">AllMusic 服务端</a>，并为需要听歌的玩家安装匹配的客户端模组。</li><li>正常启动一次，让 AllMusic 创建数据目录。</li><li>停止服务端或代理，把音乐源 JAR 放入 <strong>AllMusic 数据目录中的 <code>api/</code></strong>。上游常见路径为 <code>allmusic/api/</code>，以当前平台日志与实际生成的目录为准。音乐源不是独立 Bukkit 插件。</li><li>再次启动，检查 AllMusic 是否识别出 <code>qqmusic</code> 或 <code>kugou</code>。</li><li>使用明确的 API ID 搜索，例如 <code>/music search qqmusic 晴天</code> 或 <code>/music search kugou 晴天</code>。</li></ol><p>两种音乐源可以同时加载，<code>defaultApi</code> 决定省略音乐源 ID 时使用哪一个。修改 AllMusic 的 <code>config.json</code> 中这一项，保留其他原有配置：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;defaultApi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;qqmusic&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>使用酷狗时改为 <code>&quot;kugou&quot;</code>。添加或替换音乐源 JAR 后正常重启；单纯修改配置的重载方式以当前 AllMusic 版本为准。</p><h2 id="版本配套" tabindex="-1">版本配套 <a class="header-anchor" href="#版本配套" aria-label="Permalink to &quot;版本配套&quot;">​</a></h2><p>这些扩展依赖 AllMusic 的 <code>IMusicApi</code> 接口与核心对象，使用 Java 8 目标字节码；实际 Java 要求由运行的 AllMusic、服务端和代理共同决定。出现 <code>NoSuchMethodError</code>、<code>ClassNotFoundException</code> 等情况时，应匹配音乐源所用的 AllMusic 核心版本，或使用对应核心重新构建。</p><p><a href="./qqmusic.html">QQMusic 说明</a>与 <a href="./kugou.html">Kugou 说明</a>介绍了歌曲标识、Cookie 和构建方式。如果还需要直播弹幕点歌，再安装同一平台的 <a href="./../bilimusicbridge/">BiliMusicBridge</a>。</p>`,11)])])}const g=t(l,[["render",o]]);export{p as __pageData,g as default};
